using System;
using System.Linq;
using System.Reflection;
using UnityEngine;
namespace BWVR.Editor {
public static class CatchGameChecks {
 static readonly BindingFlags F=BindingFlags.Instance|BindingFlags.NonPublic;
 static void Check(bool ok,string why){if(!ok)throw new Exception(why);}
 public static void VerifyModel(){
  var old=new SliceState();string json=JsonUtility.ToJson(old);CreationBookText.Read(old,CreationBookSection.Creature,1);Check(JsonUtility.ToJson(old)==json&&old.Valid(),"Book read initializes old catch history");
  var empty=new CatchMemory{control=0,preference=0};Check(empty.Control==.15f&&empty.Willingness==.5f,"Empty inline old-save history lost neutral defaults");var m=new CatchMemory{attempts=1};m.Caught();m.rolls=1;Check(m.Valid()&&m.control>.15f&&JsonUtility.FromJson<CatchMemory>(JsonUtility.ToJson(m)).Valid(),"Catch practice/save failed");m.rolls=2;Check(!m.Valid(),"More rolls than catches accepted");m.rolls=1;m.catches=2;Check(!m.Valid(),"More catches than attempts accepted");
  Check(CatchTrajectory.Intercept(new Vector3(0,10,18),new Vector3(0,3,-8),new Vector3(0,8,6),4.65f,out var t)&&t>0&&t<=1.2f,"Gentle incoming arc unavailable");Check(!CatchTrajectory.Intercept(Vector3.forward*18,Vector3.forward*8,Vector3.zero,5,out _)&&!CatchTrajectory.Intercept(Vector3.forward*18,Vector3.back*20,Vector3.zero,5,out _)&&!CatchTrajectory.Intercept(Vector3.zero,new Vector3(float.NaN,0,0),Vector3.zero,5,out _),"Away/fast/nonfinite trajectory accepted");
  var state=new SliceState();state.Hybrid.receipt.catchBall=true;state.Hybrid.receipt.action=CreatureAction.WaterDelivery;Check(!state.Valid(),"Invalid catch teaching receipt accepted");Debug.Log("BWVR_CATCH_MODEL_PASS");
 }
 public static void VerifyRuntime(Action<string,BeachBall> capture=null){
  var slice=UnityEngine.Object.FindAnyObjectByType<QuestSlice>();var field=typeof(QuestSlice).GetField("state",F);var original=(SliceState)field.GetValue(slice);var god=slice.GetComponentInChildren<CreatureHybrid>();var mind=god.GetComponent<CreatureCuriosity>();var nav=slice.GetComponent<IslandNavigation>();var ball=slice.GetComponentsInChildren<BeachBall>().First();var item=ball.GetComponent<CarryItem>();var world=slice.GetComponentInChildren<VillageResources>();var actors=slice.GetComponentsInChildren<VillagerRoutine>();var positions=actors.Select(a=>a.transform.position).ToArray();var held=actors.Select(a=>a.GetComponent<CarryItem>().held).ToArray();var godAt=god.transform.position;var godRot=god.transform.rotation;var affordances=slice.GetComponentsInChildren<CreatureAffordance>();var cooldowns=affordances.Select(a=>a.cooldown).ToArray();float timeScale=Time.timeScale;Time.timeScale=0;god.Interrupt("Catch QA");var test=new SliceState{developmentFocus=true,observeWithoutFoodWork=true};field.SetValue(slice,test);test.Building.observed=15;world.ResetWorld();god.NewSeason();ball.ResetWorld();slice.GetComponentInChildren<GodToolPalette>().Cancel();
  try{
   foreach(var actor in actors){actor.ResetTask();actor.transform.position=world.StoreApproach+Vector3.up*nav.Scale*100;actor.GetComponent<CarryItem>().held=true;}
   Vector3 forward=ball.Bowling!=null?-ball.Bowling.Forward:Vector3.forward;forward.y=0;forward.Normalize();var centre=nav.ProjectFoot(item.home,nav.creature);god.transform.SetPositionAndRotation(centre,Quaternion.LookRotation(forward));god.GetComponent<IslandNavigator>().ResetRoute();Physics.SyncTransforms();
   void Quiet(){foreach(var a in affordances)a.cooldown=god.State.time+10000;ball.GetComponent<CreatureAffordance>().cooldown=0;}
   void Toss(float speed=8){ball.ReturnHome();Quiet();ball.transform.position=god.transform.position+(forward*18+Vector3.up*10)*nav.Scale;Check(ball.PlayerToss(-forward*(speed/18)),"Native player toss failed");}
   void Step(float dt=.02f){ball.Advance(dt,test.paused);god.Tick(dt);}
   void Begin(){Toss();Check(ball.CatchReady,"Incoming toss was not catchable");god.Tick(.02f);Check(god.Owner==CreatureHybrid.ActionOwner.Curiosity&&mind.Current==CreatureCuriosity.Phase.CatchBall,"Utility did not choose native catch: "+god.Owner+" / "+mind.Current+" / "+god.Explanation);}
   void Round(string label){Begin();int oldCatches=test.WorldPlay.Catch.catches;for(int i=0;i<85&&mind.Current==CreatureCuriosity.Phase.CatchBall;i++)Step();Check(mind.Current==CreatureCuriosity.Phase.CatchReturn&&mind.Holding==item&&item.held&&test.WorldPlay.Catch.catches==oldCatches+1,"Physical ball never reached/caught the hands");capture?.Invoke(label+"-caught",ball);for(int i=0;i<65&&god.Owner!=CreatureHybrid.ActionOwner.None;i++)Step();Check(god.Owner==CreatureHybrid.ActionOwner.None&&mind.Holding==null&&!item.held&&ball.Body.linearVelocity.magnitude<=7.2f&&Vector3.Dot(ball.Body.linearVelocity,forward)>2,"Caught ball was not physically rolled back");var rollStart=ball.Body.position;ball.Advance(.1f,false);Check(Vector3.Dot(ball.Body.position-rollStart,forward)>.01f,"Released roll did not actually move toward the toss origin");Check(god.State.receipt.catchBall&&god.State.receipt.eligible&&test.Valid(),"Catch/roll completion receipt invalid");capture?.Invoke(label+"-rolled",ball);}
   Round("first");Check(test.WorldPlay.Catch.attempts==1&&test.WorldPlay.Catch.catches==1&&test.WorldPlay.Catch.rolls==1&&test.WorldPlay.fetchReturns==0,"Catch and fetch progress conflated");float preference=test.WorldPlay.Catch.preference,control=test.WorldPlay.Catch.control;Check(god.Feedback(true)&&test.WorldPlay.Catch.preference>preference,"Praise did not teach catching");float taught=test.WorldPlay.Catch.preference;god.Feedback(true);Check(test.WorldPlay.Catch.preference==taught,"One catch reinforced twice");
   Round("second");Check(test.WorldPlay.Catch.control>control&&god.Feedback(false)&&test.WorldPlay.Catch.preference<taught,"Practice and discouragement were not separate");
   int catches=test.WorldPlay.Catch.catches,rolls=test.WorldPlay.Catch.rolls;Toss(20);Check(!ball.CatchReady,"Fast throw offered a catch");test.paused=true;Check(!ball.PlayerToss(-forward)&&!ball.CatchReady,"Paused throw/catch accepted");test.paused=false;
   Begin();test.paused=true;string paused=JsonUtility.ToJson(test);var frozen=ball.Body.position;ball.Advance(2,true);god.Tick(2);Check(JsonUtility.ToJson(test)==paused&&ball.Body.position==frozen,"Pause advanced catching");test.paused=false;
   // A player grab during anticipation stays player-owned through cancellation.
   item.held=true;item.GetComponent<Collider>().enabled=false;god.Tick(.02f);Check(item.held&&!item.GetComponent<Collider>().enabled&&mind.Holding==null&&god.Owner==CreatureHybrid.ActionOwner.None,"Creature stole/released player grab");item.held=false;item.GetComponent<Collider>().enabled=true;
   Begin();ball.EnvironmentalImpulse(Vector3.right);god.Tick(.02f);Check(god.Owner==CreatureHybrid.ActionOwner.None&&mind.Holding==null&&test.WorldPlay.Catch.catches==catches,"Wind interruption counted a catch");
   Begin();ball.Body.position+=Vector3.right*50;ball.transform.position=nav.ToWorld(ball.Body.position);for(int i=0;i<90&&god.Owner!=CreatureHybrid.ActionOwner.None;i++)god.Tick(.02f);Check(god.Owner==CreatureHybrid.ActionOwner.None&&test.WorldPlay.Catch.catches==catches&&test.WorldPlay.Catch.rolls==rolls,"Missed ball teleported or counted");
   Begin();god.Interrupt("Player interrupted catch");Check(!ball.OwnsCatch&&mind.Holding==null&&test.WorldPlay.Catch.catches==catches,"Interruption retained catch/carry ownership");
   Begin();for(int i=0;i<85&&mind.Current==CreatureCuriosity.Phase.CatchBall;i++)Step();Check(mind.Current==CreatureCuriosity.Phase.CatchReturn,"No caught ball for carry cancellation");catches++;var carryAt=ball.transform.position;god.Interrupt("Player interrupted immediately after catch");ball.Advance(.02f,false);Check(!item.held&&!ball.Body.isKinematic&&!ball.OwnsCatch&&test.WorldPlay.Catch.catches==catches&&test.WorldPlay.Catch.rolls==rolls&&Vector3.Distance(carryAt,ball.transform.position)<nav.Scale,"Caught interruption froze or rewound the ball / erased practice");
   typeof(QuestSlice).GetMethod("Save",F).Invoke(slice,null);typeof(QuestSlice).GetMethod("Load",F).Invoke(slice,null);test=(SliceState)field.GetValue(slice);god.NewSeason();ball.ResetWorld();Check(test.Valid()&&test.WorldPlay.Catch.catches==catches&&test.WorldPlay.Catch.rolls==rolls&&test.WorldPlay.Catch.preference<taught&&!ball.CatchReady&&!ball.OwnsCatch,"Save/resume lost learning or revived an in-flight catch");
   Debug.Log("BWVR_CATCH_RUNTIME_PASS: native toss/utility/physical capture/grounded roll; two completed bouts; praise once and discouragement; skill persists; fast throw, player grab, pause, wind, miss, interruption; native Save/Load with no resumed physics");
  }finally{god.Interrupt("Catch QA restore");field.SetValue(slice,original);world.ResetWorld();god.NewSeason();ball.ResetWorld();god.transform.SetPositionAndRotation(godAt,godRot);for(int i=0;i<actors.Length;i++){actors[i].transform.position=positions[i];actors[i].GetComponent<CarryItem>().held=held[i];}for(int i=0;i<affordances.Length;i++)affordances[i].cooldown=cooldowns[i];Time.timeScale=timeScale;}
 }
}
}
